import java.util.*;

class Solution {
    public boolean canSplit(int[][] graph) {
        int n = graph.length;
        int[] color = new int[n];
        Arrays.fill(color, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int s = 0; s < n; s++) {
            if (color[s] != -1) continue; // new component
            color[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (int u : graph[v]) {
                    if (color[u] == -1) { color[u] = 1 - color[v]; q.add(u); }
                    else if (color[u] == color[v]) return false; // same team on one edge
                }
            }
        }
        return true;
    }
}

